--
-- Table structure for table `buildings`
--

DROP TABLE IF EXISTS `buildings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `buildings` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `aliases` json DEFAULT NULL,
  `intro` text COLLATE utf8mb4_unicode_ci,
  `icon` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fa-solid fa-building',
  `bg_color` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#D8F3DC',
  `color` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#1B4332',
  `map_x` decimal(7,3) DEFAULT NULL,
  `map_y` decimal(7,3) DEFAULT NULL,
  `map_hidden` tinyint(1) NOT NULL DEFAULT '0',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `info` json DEFAULT NULL,
  `equipment` json DEFAULT NULL,
  `floors` json DEFAULT NULL,
  `schedule` text COLLATE utf8mb4_unicode_ci,
  `contacts` json DEFAULT NULL,
  `surroundings` json DEFAULT NULL,
  `timetable` json DEFAULT NULL,
  `model_objects` json DEFAULT NULL,
  `pin_x` decimal(9,2) DEFAULT NULL,
  `pin_z` decimal(9,2) DEFAULT NULL,
  `regions` json DEFAULT NULL,
  `surface_points` json DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_buildings_category` (`category_id`),
  KEY `idx_buildings_deleted` (`deleted_at`),
  KEY `idx_buildings_sort` (`category_id`,`sort_order`),
  CONSTRAINT `fk_buildings_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

