INSERT INTO `buildings` VALUES ('b1','teaching','第一教学楼','一教 · 教学楼','[\"一教\", \"教一\", \"第一教学楼\"]','东西走向的长条形教学楼，共 5 层。1 层设有文印室、母婴关爱室、无人便利店与在校生自助服务机，2-5 层为常规教室与教师办公室。','fa-solid fa-building','#D8F3DC','#1B4332',NULL,NULL,0,NULL,0,'[{\"kind\": \"location\", \"label\": \"位置\", \"value\": \"长条状，西-东走向\"}, {\"kind\": \"time\", \"label\": \"开门时间\", \"value\": \"待补充\"}, {\"kind\": \"time\", \"label\": \"关门时间\", \"value\": \"22:00\"}, {\"kind\": \"time\", \"label\": \"断电时间\", \"value\": \"21:45（照明、插座、空调）\"}, {\"kind\": \"booking\", \"label\": \"空闲教室查询\", \"value\": \"待补充\"}, {\"kind\": \"note\", \"label\": \"空调 / 暖气\", \"value\": \"待补充\"}, {\"kind\": \"note\", \"label\": \"备注\", \"value\": \"校历关键日期见附录；会议室 1-8 号屋\"}]','[{\"icon\": \"fa-solid fa-droplet\", \"name\": \"饮水机\", \"details\": [{\"kind\": \"text\", \"label\": \"位置\", \"value\": \"每层偏东侧开水间，各 2 台\"}, {\"kind\": \"text\", \"label\": \"配套\", \"value\": \"开水间另有 3 个洗手池\"}]}, {\"icon\": \"fa-solid fa-store\", \"name\": \"无人便利店（售卖机）\", \"details\": [{\"kind\": \"text\", \"label\": \"位置\", \"value\": \"1F 中楼梯右侧\"}, {\"kind\": \"text\", \"label\": \"售卖\", \"value\": \"饮料、零食等（自助扫码）\"}]}, {\"icon\": \"fa-solid fa-print\", \"name\": \"在校生自助服务机\", \"details\": [{\"kind\": \"text\", \"label\": \"位置\", \"value\": \"1F 正门（中）右手边，共 2 台\"}, {\"kind\": \"text\", \"label\": \"可办理\", \"value\": \"注销报到；成绩单 / 证件打印\"}, {\"kind\": \"text\", \"label\": \"故障电话\", \"value\": \"15116926012\"}]}, {\"icon\": \"fa-solid fa-heart-pulse\", \"name\": \"AED 自动体外除颤器\", \"details\": [{\"kind\": \"text\", \"label\": \"位置\", \"value\": \"1F 正门右手转角\"}, {\"kind\": \"text\", \"label\": \"备注\", \"value\": \"紧急情况取用，非紧急请勿移动\"}]}]','[{\"desc\": \"由东至西：文印室、母婴关爱室 → 洗手间与开水间 → 正门（中）→ 洗手间\", \"name\": \"1F\", \"modules\": [{\"kind\": \"location\", \"label\": \"东侧\", \"value\": \"文印室；母婴关爱室\"}, {\"kind\": \"facility\", \"label\": \"偏东侧\", \"value\": \"男、女洗手间；开水间（两台饮水机 + 3 个洗手池）\"}, {\"kind\": \"function\", \"label\": \"正门（中）\", \"value\": \"在校生自助服务机 2 台（注销报到、成绩单/证件打印）\"}, 